{"path": "robot_name.py", "content": "import random
import string


class Robot:
    _used_names = set()

    def __init__(self):
        self._name = None

    @property
    def name(self):
        if self._name is None:
            self._name = self._generate()
        return self._name

    @classmethod
    def _generate(cls):
        while True:
            candidate = (
                "".join(random.choices(string.ascii_uppercase, k=2))
                + "".join(random.choices(string.digits, k=3))
            )
            if candidate not in cls._used_names:
                cls._used_names.add(candidate)
                return candidate

    def reset(self):
        # The old name stays reserved so it is never reused.
        self._name = None
